"""Actual isolated new-schema backup/restore with a pending acknowledged report."""
import hashlib, importlib.util, json, os, subprocess, sys, time
from pathlib import Path
builder, directory=sys.argv[1:]; evidence=Path(directory)
checks_path=evidence/'checks.json'; checks=json.loads(checks_path.read_text())
if os.environ.get('GITHUB_ACTIONS')!='true' or os.environ.get('CI')!='true': raise RuntimeError('Official isolated CI only')
base='postgresql://ptool:synthetic@127.0.0.1:5432/assessment_capacity_ci_test?schema=public'
common=['docker','run','--rm','--network','host','-v',str(evidence)+':/evidence','-v',str(Path('server-version/backend/src/__tests__').resolve())+':/app/src/__tests__:ro',
 '-e','CI=true','-e','GITHUB_ACTIONS=true','-e','NODE_ENV=test','-e','JWT_SECRET=synthetic-report-ci-not-production','-e','ASSET_SIGNING_SECRET=synthetic-report-assets-not-production',
 '-e','DATA_ENCRYPTION_KEY='+'55'*32,'-e','DATA_PSEUDONYM_KEY='+'56'*32,'-e','ASSET_MIGRATION_COMPLETE=true','-e','ASSESSMENT_REPORT_ASYNC_ENABLED=true',
 '-e','ASSESSMENT_WHOLE_SUBMIT_ENABLED=true',
 '-e','ASSESSMENT_COMPACT_FACTS_ENABLED=true','-e','ASSESSMENT_SHARED_CONTROL_ENABLED=true','-e','ASSESSMENT_WHOLE_DURABLE_BACKLOG_ENABLED=true','-e','ASSESSMENT_SHARED_RUNTIME_STORAGE_ENABLED=true','-e','ASSESSMENT_COMPILED_ARTIFACT_CACHE_ENABLED=true','-e','ASSESSMENT_SCALE_COLLECTION_BATCH_ENABLED=true','-e','ASSESSMENT_REPORT_COMMITTED_CONTEXT_ENABLED=true','-e','ASSESSMENT_WHOLE_COMPACT_MANIFEST_ENABLED=true',
 '-e','UPLOAD_DIR=/tmp/report-ci-uploads','-e','EVIDENCE_UID='+str(os.getuid()),'-e','EVIDENCE_GID='+str(os.getgid())]
script=evidence/'prepare-restore.ts'
script.write_text('import {writeFileSync,chownSync} from \'node:fs\';\nimport {createHash,randomUUID} from \'node:crypto\';\nimport assert from \'node:assert/strict\';\nimport {PrismaClient} from \'/app/node_modules/@prisma/client/index.js\';\nimport {createReportOutboxFixture} from \'/app/src/__tests__/integration/report-outbox-fixture\';\nimport {requireIsolatedReleaseDatabase} from \'/app/src/__tests__/integration/integration-env\';\nimport {submitScaleAssessmentFinal} from \'/app/src/modules/scale/scale-final-submit.service\';\nimport {getWholeQuestionnaireDefinition,submitWholeQuestionnaire} from \'/app/src/modules/composite/whole-questionnaire.service\';\nimport {prisma as serviceDb} from \'/app/src/config/database\';\n(async()=>{\nrequireIsolatedReleaseDatabase(process.env.DATABASE_URL!);\nconst db=new PrismaClient();\nconst enabledFlags=["ASSESSMENT_COMPACT_FACTS_ENABLED", "ASSESSMENT_SHARED_CONTROL_ENABLED", "ASSESSMENT_WHOLE_DURABLE_BACKLOG_ENABLED", "ASSESSMENT_SHARED_RUNTIME_STORAGE_ENABLED", "ASSESSMENT_COMPILED_ARTIFACT_CACHE_ENABLED", "ASSESSMENT_SCALE_COLLECTION_BATCH_ENABLED", "ASSESSMENT_REPORT_COMMITTED_CONTEXT_ENABLED", "ASSESSMENT_WHOLE_COMPACT_MANIFEST_ENABLED"];\nfor(const k of enabledFlags)process.env[k]=\'true\';\nconst ready=await createReportOutboxFixture(db),readyAck=await submitScaleAssessmentFinal(ready.inputs[0]);\nconst readyJob=await(await import(\'/app/src/modules/assessment-runtime/report-outbox.service\')).claimCompositeReportJob();assert(readyJob&&readyJob.attemptId===ready.parent.id);await(await import(\'/app/src/workers/compositeReportWorker\')).processCompositeReportJob(readyJob);\nassert.equal((await db.compositeReportJob.findUniqueOrThrow({where:{id:readyJob.id}})).status,\'READY\');\nconst readyReport=await(await import(\'/app/src/modules/composite/composite.service\')).getReport(ready.parent.id,{userId:ready.participant.id});\nconst readyChild=await db.assessment.findUniqueOrThrow({where:{id:ready.inputs[0].assessmentId}});assert.equal((readyChild.result as any).k,\'SFF1\');\nconst sample=JSON.parse((await import(\'node:fs\')).readFileSync(\'/app/src/__tests__/fixtures/cognitive-storage.synthetic.json\',\'utf8\'));\nconst cognitiveReference=await(await import(\'/app/src/modules/assessment-runtime/shared-cognitive-runtime\')).storeSharedCognitiveRuntime(sample.runtime);\nfor(const k of enabledFlags)process.env[k]=\'false\';\n\nconst f=await createReportOutboxFixture(db),ack=await submitScaleAssessmentFinal(f.inputs[0]);\nfor(const k of enabledFlags)process.env[k]=\'true\';\nconst whole=await createReportOutboxFixture(db,2),definition=await getWholeQuestionnaireDefinition(whole.parent.id,{userId:whole.participant.id});\nconst children=await db.assessment.findMany({where:{compositeAttemptId:whole.parent.id},select:{id:true,compositeItemId:true}});\nconst input={submissionId:\'restore-whole-\'+randomUUID(),attemptEpoch:1,slotSetHash:definition.slotSetHash!,contextSnapshotHash:definition.contextSnapshotHash,\n units:definition.units.map(unit=>({itemId:unit.itemId,definitionHash:unit.definitionHash,answers:whole.inputs.find(v=>v.assessmentId===children.find(c=>c.compositeItemId===unit.itemId)!.id)!.answers}))};\nconst receipt=await submitWholeQuestionnaire(whole.parent.id,input,{userId:whole.participant.id});\nconst job=await db.compositeReportJob.findUniqueOrThrow({where:{attemptId_attemptEpoch:{attemptId:whole.parent.id,attemptEpoch:1}}});\nassert.equal(receipt.status,\'ACCEPTED\');assert.equal(job.status,\'PENDING\');assert(!job.budgetHeld&&job.wholeAnswersEncrypted&&job.wholeValidationEncrypted);assert(job.wholeValidationEncrypted!.startsWith(\'ekr1\')); \nassert.equal(await db.assessmentUnitSnapshot.count({where:{compositeAttemptId:whole.parent.id}}),0);\nassert.equal(await db.assessment.count({where:{compositeAttemptId:whole.parent.id,status:\'IN_PROGRESS\'}}),2);\nwriteFileSync(\'/evidence/restore-fixture.json\',JSON.stringify({ready:{attemptId:ready.parent.id,participantId:ready.participant.id,reportHash:createHash(\'sha256\').update(JSON.stringify(readyReport)).digest(\'hex\'),assessmentId:readyChild.id},cognitive:{reference:cognitiveReference,runtimeHash:createHash(\'sha256\').update(JSON.stringify(sample.runtime)).digest(\'hex\')},attemptId:f.parent.id,participantId:f.participant.id,assessmentId:f.inputs[0].assessmentId,submissionId:ack.submissionId,payloadHash:ack.payloadHash,\n whole:{attemptId:whole.parent.id,participantId:whole.participant.id,submissionId:receipt.submissionId,payloadHash:receipt.payloadHash,acceptedAt:receipt.acceptedAt.toISOString(),\n answersCipherSha256:createHash(\'sha256\').update(job.wholeAnswersEncrypted!).digest(\'hex\'),validationCipherSha256:createHash(\'sha256\').update(job.wholeValidationEncrypted!).digest(\'hex\'),\n units:children.map(c=>({assessmentId:c.id,itemId:c.compositeItemId,submissionId:\'whole-\'+createHash(\'sha256\').update(input.submissionId+\'/\'+c.compositeItemId).digest(\'hex\')}))}}));\nchownSync(\'/evidence/restore-fixture.json\',Number(process.env.EVIDENCE_UID),Number(process.env.EVIDENCE_GID));\nawait db.$disconnect();await serviceDb.$disconnect();\n})().catch(e=>{console.error(e);process.exit(1)});\n')
subprocess.run(common+['-e','DATABASE_URL='+base,builder,'npx','tsx','/evidence/prepare-restore.ts'],check=True,timeout=60)
archive=evidence/'pending-report.dump'
with archive.open('wb') as out:subprocess.run(['docker','exec','assessment-capacity-ci-postgres','pg_dump','-U','ptool','-Fc','assessment_capacity_ci_test'],stdout=out,check=True,timeout=60)
subprocess.run(['docker','exec','assessment-capacity-ci-postgres','createdb','-U','ptool','assessment_restore_ci_test'],check=True,timeout=30)
with archive.open('rb') as source:subprocess.run(['docker','exec','-i','assessment-capacity-ci-postgres','pg_restore','-U','ptool','-d','assessment_restore_ci_test'],stdin=source,check=True,timeout=90)
role='report_ci_runtime'
subprocess.run(['docker','exec','assessment-capacity-ci-postgres','psql','-U','ptool','-d','assessment_restore_ci_test','-v','ON_ERROR_STOP=1','-c',"CREATE ROLE report_ci_runtime LOGIN PASSWORD 'synthetic-runtime' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; REVOKE CREATE ON SCHEMA public FROM PUBLIC; GRANT USAGE ON SCHEMA public TO report_ci_runtime;"],check=True,timeout=30)
policy=json.loads(Path('server-version/backend/scripts/runtime-table-policy.json').read_text())
for table, category in policy['tables'].items():
    if category=='OPERATOR_ONLY':continue
    privileges='SELECT,INSERT,UPDATE,DELETE' if category=='RUNTIME_RW' else 'SELECT'
    subprocess.run(['docker','exec','assessment-capacity-ci-postgres','psql','-U','ptool','-d','assessment_restore_ci_test','-v','ON_ERROR_STOP=1','-q','-c',f'GRANT {privileges} ON TABLE "{table}" TO {role}'],check=True,stdout=subprocess.DEVNULL,timeout=10)
# All runtime sequences are owned by already classified runtime tables. Preserve
# the established restriction: operator sequences receive no runtime privilege.
query="SELECT c.relname,owning.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_depend d ON d.classid='pg_class'::regclass AND d.refclassid='pg_class'::regclass AND d.objid=c.oid AND d.deptype IN ('a','i') JOIN pg_class owning ON owning.oid=d.refobjid WHERE n.nspname='public' AND c.relkind='S'"
rows=subprocess.check_output(['docker','exec','assessment-capacity-ci-postgres','psql','-U','ptool','-d','assessment_restore_ci_test','-At','-F','|','-c',query],text=True).strip().splitlines()
for row in rows:
    sequence, table=row.split('|')
    if policy['tables'].get(table)=='RUNTIME_RW':subprocess.run(['docker','exec','assessment-capacity-ci-postgres','psql','-U','ptool','-d','assessment_restore_ci_test','-q','-c',f'GRANT USAGE,SELECT ON SEQUENCE "{sequence}" TO {role}'],check=True,stdout=subprocess.DEVNULL,timeout=10)
runtime='postgresql://report_ci_runtime:synthetic-runtime@127.0.0.1:5432/assessment_restore_ci_test?schema=public'
verify=evidence/'verify-restore.cjs'
verify.write_text("const fs=require('fs'),assert=require('assert/strict'),{createHash}=require('crypto');\nconst {prisma}=require('/app/dist/config/database'),outbox=require('/app/dist/modules/assessment-runtime/report-outbox.service');\nconst wholeService=require('/app/dist/modules/composite/whole-questionnaire.service');\nconst {decryptUnifiedRuntimePayload}=require('/app/dist/modules/assessment-runtime/security');\n(async()=>{\nconst expected=JSON.parse(fs.readFileSync('/evidence/restore-fixture.json')),before=await prisma.assessment.findUniqueOrThrow({where:{id:expected.assessmentId}});\nassert.equal(before.submissionId,expected.submissionId);assert.equal(before.submissionPayloadHash,expected.payloadHash);\nconst w=expected.whole,raw=await outbox.readWholeQuestionnaireReceipt(w.attemptId,1);\nassert.equal(raw.wholeSubmissionId,w.submissionId);assert.equal(raw.wholePayloadHash,w.payloadHash);assert.equal(raw.wholeAcceptedAt.toISOString(),w.acceptedAt);\nassert.equal(createHash('sha256').update(raw.wholeAnswersEncrypted).digest('hex'),w.answersCipherSha256);\nassert.equal(createHash('sha256').update(raw.wholeValidationEncrypted).digest('hex'),w.validationCipherSha256);\nassert.equal(raw.status,'PENDING');assert.equal((await outbox.readCompositeReportJob(w.attemptId,1)).budgetHeld,false);\nassert.equal(await prisma.assessmentUnitSnapshot.count({where:{compositeAttemptId:w.attemptId}}),0);\nconst packed=decryptUnifiedRuntimePayload(raw.wholeAnswersEncrypted);assert.equal(packed.kind,'WHOLE_RAW_FACTS');\nconst envelope=require('/app/dist/modules/assessment-runtime/compact-raw').unpackWholeRawEnvelope(packed);\nassert.equal(envelope.units.length,2);assert.equal(envelope.units.reduce((n,u)=>n+u.answers.length,0),6);\nconst remaining=new Set([expected.attemptId,w.attemptId]);\nfor(let i=0;i<2;i++){const job=await outbox.claimCompositeReportJob();assert(job&&remaining.delete(job.attemptId));await require('/app/dist/workers/compositeReportWorker').processCompositeReportJob(job);}\nassert.equal(remaining.size,0);\nfor(const id of [expected.attemptId,w.attemptId])assert.equal((await outbox.readCompositeReportJob(id,1)).status,'READY');\nconst service=require('/app/dist/modules/composite/composite.service');\nconst ready=expected.ready,readyBefore=await prisma.compositeReportJob.findUniqueOrThrow({where:{attemptId_attemptEpoch:{attemptId:ready.attemptId,attemptEpoch:1}}}),readyReport=await service.getReport(ready.attemptId,{userId:ready.participantId}),readyAfter=await prisma.compositeReportJob.findUniqueOrThrow({where:{id:readyBefore.id}});\nassert.equal(createHash('sha256').update(JSON.stringify(readyReport)).digest('hex'),ready.reportHash);assert.equal(readyAfter.updatedAt.getTime(),readyBefore.updatedAt.getTime());assert.equal(readyAfter.reportEncrypted,readyBefore.reportEncrypted);\nassert.equal((await prisma.assessment.findUniqueOrThrow({where:{id:ready.assessmentId}})).result.k,'SFF1');\nconst cognitive=await require('/app/dist/modules/assessment-runtime/shared-cognitive-runtime').loadSharedCognitiveRuntime(expected.cognitive.reference);assert.equal(createHash('sha256').update(JSON.stringify(cognitive.snapshot)).digest('hex'),expected.cognitive.runtimeHash);\nconst legacyReport=await service.getReport(expected.attemptId,{userId:expected.participantId});assert.equal(legacyReport.unitReports[0].scores[0].value,3);\nconst report=await service.getReport(w.attemptId,{userId:w.participantId});assert.equal(report.unitReports.length,2);assert(report.unitReports.every(u=>u.scores[0].value===3));\nfor(const unit of w.units){const child=await prisma.assessment.findUniqueOrThrow({where:{id:unit.assessmentId}});assert.equal(child.submissionId,unit.submissionId);assert(child.submissionPayloadHash);assert.equal(child.status,'COMPLETED');}\nassert.equal(await prisma.assessmentUnitSnapshot.count({where:{compositeAttemptId:w.attemptId}}),2);\nconst replay=await wholeService.submitWholeQuestionnaire(w.attemptId,{submissionId:w.submissionId,attemptEpoch:1,slotSetHash:envelope.binding.slotSetHash,contextSnapshotHash:envelope.binding.contextHash,\n units:envelope.units.map(u=>({itemId:u.itemId,definitionHash:u.definitionHash,answers:u.answers,...(u.deviceInputProvenance?{deviceInputProvenance:u.deviceInputProvenance}:{})}))},{userId:w.participantId});\nassert.equal(replay.replayed,true);assert.equal(replay.payloadHash,w.payloadHash);\nassert.equal((await prisma.compositeReportQueueBudget.findUniqueOrThrow({where:{id:'reports'}})).pending,0);\nfs.writeFileSync('/evidence/recovery-result.json',JSON.stringify({status:'success',receiptPreserved:true,pendingReportRecovered:true,restrictedRuntimeRole:true,scoreVerified:true,wholeEnvelopePreserved:true,wholePendingBeforeCanonical:true,wholeAnswersRecovered:true,wholeCanonicalIdentityPreserved:true,wholeReplayAfterRestoreVerified:true,compactFactsRestored:true,sharedControlRestored:true,sharedCognitiveRuntimeRestored:true,readyReadDidNotRegenerate:true}));\nfs.chownSync('/evidence/recovery-result.json',Number(process.env.EVIDENCE_UID),Number(process.env.EVIDENCE_GID));await prisma.$disconnect();\n})().catch(e=>{console.error(e);process.exit(1)});\n")
subprocess.run(common+['-e','DATABASE_URL='+runtime,'-e','DATABASE_URL_RUNTIME='+runtime,builder,'node','scripts/runtime-role-contract.mjs','verify-current'],check=True,timeout=30)
subprocess.run(common+['-e','DATABASE_URL='+runtime,builder,'node','/evidence/verify-restore.cjs'],check=True,timeout=90)
result=json.loads((evidence/'recovery-result.json').read_text());assert result['status']=='success'
result['backupSha256']=hashlib.sha256(archive.read_bytes()).hexdigest();result['schemaMigration']='20261015030000_whole_validation_manifest';result['at']=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())
(evidence/'recovery-result.json').write_text(json.dumps(result,indent=2))
# Synthetic dump is not a production backup. Keep its digest and real restore
# results; the disposable container and all fixture files are removed by CI.
archive.unlink()
script.unlink();verify.unlink()
